#!/usr/bin/env bash
# seed-ref-vocab.sh — load the nhdw_ref vocabulary (generated by
# bundle/seeds/ref-vocab/build_vocab.py) into Postgres. Idempotent upsert; safe to
# re-run any time. Runs the loader THROUGH the postgres pod (kubectl exec + COPY
# FROM STDIN), matching how the other seed scripts reach in-cluster Postgres.
#
# Boot-order contract: once a resolution view JOINs nhdw_ref (the parity-first
# migrations), this MUST run before the dbt-vault job — wire it as the bootstrap
# step immediately before the pipeline stage in that same change.
#
# Usage:  bundle/scripts/seed-ref-vocab.sh              # build if stale, then load
#         bundle/scripts/seed-ref-vocab.sh --no-build   # load the committed _build as-is
set -euo pipefail
REPO="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"
VOCAB="$REPO/bundle/seeds/ref-vocab"
NS="${NS:-nhdw}"
POD="${POD:-postgres-vault-0}"
DB="${DB:-nhdw_vault}"
PGUSER="${PGUSER:-vault_admin}"

log(){ echo "▸ ref-vocab: $*"; }

if [ "${1:-}" != "--no-build" ]; then
  python3 "$VOCAB/build_vocab.py" >/dev/null
  python3 "$VOCAB/test_build_vocab.py" >/dev/null || { echo "✗ vocab tests failed — not loading" >&2; exit 1; }
  log "CSVs generated + tests green"
fi

PSQL(){ kubectl -n "$NS" exec -i "$POD" -- psql -q -U "$PGUSER" -d "$DB" "$@"; }

# Load order respects FKs. Each table: COPY into a temp clone → upsert → temp dropped
# at commit. Metamodel rows update in place; crosswalk/concept rows are keyed on their
# bitemporal PK, so a superseded mapping (new valid_from) inserts alongside history.
# The whole load goes in as a SCRIPT on stdin, not as `psql -c`. psql sends a
# -c string as ONE simple query, and when the batch reaches COPY ... FROM STDIN
# it has no way to switch the same channel over to copy data — it gives up with
# "unexpected COPY_IN result, aborting connection". Inline the CSV after the
# COPY and terminate it with \. instead. The explicit transaction is required
# too: ON COMMIT DROP would drop the temp table the instant the CREATE
# autocommits, leaving the COPY with no target.
# (A data line consisting of exactly \. would end the stream early. Nothing in a
# vocabulary CSV looks like that, and the row-count assertion below would catch
# it if it ever did.)
load(){ # $1=table  $2=conflict-key  $3=update-set
  local t="$1" key="$2" set="$3" csv="$VOCAB/_build/$1.csv"
  local cols; cols="$(head -1 "$csv")"
  local rows=$(($(wc -l < "$csv") - 1))
  {
    echo "BEGIN;"
    echo "CREATE TEMP TABLE _in (LIKE nhdw_ref.$t INCLUDING DEFAULTS) ON COMMIT DROP;"
    echo "COPY _in ($cols) FROM STDIN WITH (FORMAT csv, NULL '');"
    # strip CR: COPY locks onto the newline convention of the first data row,
    # so a CRLF csv plus an LF terminator line fails with "unquoted newline
    # found in data". build_vocab.py writes LF now; this keeps an older
    # pre-built _build/ from breaking the load.
    tail -n +2 "$csv" | tr -d '\r'
    echo "\\."
    echo "INSERT INTO nhdw_ref.$t ($cols)"
    echo "  SELECT $cols FROM _in"
    echo "  ON CONFLICT ($key) DO UPDATE SET $set;"
    echo "COMMIT;"
  } | PSQL -v ON_ERROR_STOP=1 >/dev/null || {
    echo "✗ vocabulary load failed for $t" >&2; exit 1; }
  log "loaded $t ($rows rows)"
}

load vocabulary   "vocabulary_id" \
  "vocabulary_name=EXCLUDED.vocabulary_name, vocabulary_reference=EXCLUDED.vocabulary_reference, vocabulary_version=EXCLUDED.vocabulary_version, is_source_vocabulary=EXCLUDED.is_source_vocabulary"
load domain        "domain_id"        "domain_name=EXCLUDED.domain_name"
load concept_class "concept_class_id" "concept_class_name=EXCLUDED.concept_class_name"
load concept      "vocabulary_id, concept_code, valid_from" \
  "concept_name=EXCLUDED.concept_name, domain_id=EXCLUDED.domain_id, concept_class_id=EXCLUDED.concept_class_id, standard_concept=EXCLUDED.standard_concept, valid_to=EXCLUDED.valid_to, invalid_reason=EXCLUDED.invalid_reason"
load concept_relationship "concept_id_1, concept_id_2, relationship_id, valid_from" \
  "valid_to=EXCLUDED.valid_to, invalid_reason=EXCLUDED.invalid_reason"
load source_to_concept_map "source_code, source_vocabulary_id, valid_from" \
  "source_code_description=EXCLUDED.source_code_description, target_concept_id=EXCLUDED.target_concept_id, valid_to=EXCLUDED.valid_to, invalid_reason=EXCLUDED.invalid_reason, change_source=EXCLUDED.change_source, loaded_by=EXCLUDED.loaded_by"

# The concept upsert conflicts on the UNIQUE (vocabulary_id, concept_code, valid_from)
# index rather than the PK, so a registry re-run can never fork an id: assert that.
PSQL -tAc "SELECT count(*) FROM (SELECT concept_id FROM nhdw_ref.concept GROUP BY concept_id HAVING count(*)>1) d;" \
  | grep -qx 0 || { echo "✗ duplicate concept_id detected after load" >&2; exit 1; }

log "done — $(PSQL -tAc 'SELECT count(*) FROM nhdw_ref.concept;') concepts, $(PSQL -tAc 'SELECT count(*) FROM nhdw_ref.source_to_concept_map;') crosswalk rows"
